<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Masuk Admin | Penjualan Gas</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        :root{--navy:#081b3a;--navy-dark:#041027;--blue:#2187e8;--blue-soft:#82c3fb;--canvas:#f5f8fc;--text:#10213d;--muted:#69778d;--line:#dce5f0;--danger:#bd2636}*{box-sizing:border-box}body{min-height:100vh;margin:0;color:var(--text);background:var(--canvas);font-family:"Plus Jakarta Sans",Arial,sans-serif}.login-page{min-height:100vh;display:grid;grid-template-columns:minmax(360px,46%) 1fr}.brand-panel{position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;padding:clamp(2rem,5vw,4.5rem);color:#fff;background:linear-gradient(145deg,var(--navy-dark),#123462)}.brand-panel:before,.brand-panel:after{position:absolute;content:"";border:1px solid rgba(130,195,251,.18);border-radius:50%;pointer-events:none}.brand-panel:before{width:42rem;height:42rem;right:-24rem;top:-14rem}.brand-panel:after{width:28rem;height:28rem;left:-17rem;bottom:-13rem}.brand,.intro,.panel-footer{position:relative;z-index:1}.brand{display:flex;align-items:center;gap:.8rem;font-weight:800;letter-spacing:-.03em}.brand-mark{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;color:var(--navy);background:#fff;box-shadow:0 10px 30px rgba(0,0,0,.2)}.brand-mark svg{width:25px;height:25px}.brand small{display:block;margin-top:2px;color:var(--blue-soft);font-size:.65rem;font-weight:700;letter-spacing:.13em;text-transform:uppercase}.intro{max-width:440px;margin:4rem 0}.intro-tag{display:inline-flex;align-items:center;gap:.5rem;padding:.45rem .7rem;border:1px solid rgba(130,195,251,.3);border-radius:999px;color:var(--blue-soft);font-size:.72rem;font-weight:700;letter-spacing:.07em;text-transform:uppercase}.intro-tag:before{width:7px;height:7px;border-radius:50%;background:#5be0ac;box-shadow:0 0 0 4px rgba(91,224,172,.13);content:""}.intro h2{margin:1.35rem 0 1rem;font-size:clamp(2rem,4vw,3.45rem);line-height:1.1;letter-spacing:-.055em}.intro p{margin:0;max-width:390px;color:#b8cff0;font-size:1rem;line-height:1.75}.panel-footer{color:#91afd5;font-size:.76rem}.form-panel{display:grid;place-items:center;padding:2rem}.login-card{width:min(100%,420px)}.mobile-brand{display:none}.heading-eyebrow{margin:0 0 .75rem;color:var(--blue);font-size:.72rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.login-card h1{margin:0;font-size:1.8rem;letter-spacing:-.04em}.heading-copy{margin:.65rem 0 2rem;color:var(--muted);font-size:.92rem;line-height:1.6}.alert-error{display:flex;gap:.7rem;align-items:flex-start;margin:0 0 1.35rem;padding:.85rem 1rem;border:1px solid #f1cbd0;border-radius:10px;color:#942330;background:#fff6f7;font-size:.83rem;line-height:1.5}.alert-error svg{flex:0 0 18px;margin-top:1px}.field{margin-bottom:1.2rem}.field label{display:block;margin-bottom:.5rem;color:#33445f;font-size:.83rem;font-weight:700}.field-wrap{position:relative}.field-icon{position:absolute;top:50%;left:.9rem;width:18px;height:18px;color:#8493a8;pointer-events:none;transform:translateY(-50%)}.field input{width:100%;height:50px;padding:0 2.8rem 0 2.75rem;border:1px solid var(--line);border-radius:10px;outline:0;color:var(--text);background:#fff;font:inherit;font-size:.9rem;transition:border-color .18s,box-shadow .18s}.field input::placeholder{color:#a4b0c0}.field input:focus{border-color:var(--blue);box-shadow:0 0 0 4px rgba(33,135,232,.12)}.field input.is-invalid{border-color:var(--danger)}.password-toggle{position:absolute;top:50%;right:.55rem;display:grid;place-items:center;width:35px;height:35px;padding:0;border:0;border-radius:7px;color:#65758b;background:transparent;cursor:pointer;transform:translateY(-50%)}.password-toggle:hover,.password-toggle:focus-visible{color:var(--blue);background:#eff7ff;outline:0}.field-error{display:block;margin-top:.45rem;color:var(--danger);font-size:.77rem}.form-options{display:flex;align-items:center;gap:.75rem;margin:.15rem 0 1.5rem}.form-options input{width:16px;height:16px;margin:0;accent-color:var(--blue)}.form-options label{color:var(--muted);font-size:.82rem}.signin-button{display:flex;align-items:center;justify-content:center;gap:.55rem;width:100%;height:51px;border:0;border-radius:10px;color:#fff;background:var(--blue);box-shadow:0 10px 20px rgba(33,135,232,.2);cursor:pointer;font:inherit;font-size:.9rem;font-weight:700;transition:transform .18s,background .18s}.signin-button:hover{background:#1174d1;transform:translateY(-1px)}.signin-button:focus-visible{outline:3px solid rgba(33,135,232,.3);outline-offset:3px}.signin-button svg{width:18px;height:18px}.security-note{display:flex;justify-content:center;gap:.4rem;margin:1.4rem 0 0;color:#8794a6;font-size:.75rem;text-align:center}.security-note svg{width:15px;height:15px;color:#6eae90}@media(max-width:760px){.login-page{display:block}.brand-panel{display:none}.form-panel{min-height:100vh;padding:1.5rem;align-items:start}.login-card{margin-top:2rem}.mobile-brand{display:flex;align-items:center;gap:.65rem;margin-bottom:3.4rem;color:var(--navy);font-size:.95rem;font-weight:800}.mobile-brand .brand-mark{width:36px;height:36px;background:var(--navy);color:#fff;box-shadow:none}}
    </style>
</head>
<body>
    <main class="login-page">
        <section class="brand-panel" aria-label="Informasi sistem">
            <div class="brand"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2v20M4.5 6.5h15M5.5 17.5h13M7.5 2.8v18.4M16.5 2.8v18.4"/></svg></span><span>Penjualan Gas<small>Management System</small></span></div>
            <div class="intro"><span class="intro-tag">Sistem aman & aktif</span><h2>Kelola operasional dengan lebih mudah.</h2><p>Akses dashboard untuk memantau pelanggan, stok produk, dan aktivitas penjualan gas Anda.</p></div>
            <p class="panel-footer">© {{ date('Y') }} Penjualan Gas · Akses terbatas untuk administrator.</p>
        </section>
        <section class="form-panel">
            <div class="login-card">
                <div class="mobile-brand"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2v20M4.5 6.5h15M5.5 17.5h13M7.5 2.8v18.4M16.5 2.8v18.4"/></svg></span> Penjualan Gas</div>
                <p class="heading-eyebrow">Portal Administrator</p><h1>Selamat datang kembali</h1><p class="heading-copy">Masukkan kredensial administrator Anda untuk melanjutkan.</p>
                @if (session('status'))
                    <div class="security-note" role="status">{{ session('status') }}</div>
                @endif
                @if (session('error'))
                    <div class="alert-error" role="alert"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 8v5M12 16h.01"/></svg><span>{{ session('error') }}</span></div>
                @endif
                <form method="POST" action="{{ route('admin.login.submit') }}">
                    @csrf
                    <div class="field"><label for="email">Alamat email</label><div class="field-wrap"><svg class="field-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg><input id="email" type="email" name="email" value="{{ old('email') }}" placeholder="nama@perusahaan.com" autocomplete="email" required autofocus class="@error('email') is-invalid @enderror"></div>@error('email')<small class="field-error">{{ $message }}</small>@enderror</div>
                    <div class="field"><label for="password">Kata sandi</label><div class="field-wrap"><svg class="field-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg><input id="password" type="password" name="password" placeholder="Masukkan kata sandi" autocomplete="current-password" required><button class="password-toggle" type="button" aria-label="Tampilkan kata sandi" aria-pressed="false" data-password-toggle><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg></button></div>@error('password')<small class="field-error">{{ $message }}</small>@enderror</div>
                    <div class="form-options"><input id="remember" type="checkbox" name="remember" value="1" {{ old('remember') ? 'checked' : '' }}><label for="remember">Ingat saya di perangkat ini</label></div>
                    <button class="signin-button" type="submit"><span>Masuk ke Dashboard</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>
                </form>
                <p class="security-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>Koneksi Anda dilindungi dan dienkripsi.</p>
            </div>
        </section>
    </main>
    <script>
        const passwordToggle=document.querySelector('[data-password-toggle]');const passwordInput=document.getElementById('password');passwordToggle.addEventListener('click',()=>{const showPassword=passwordInput.type==='password';passwordInput.type=showPassword?'text':'password';passwordToggle.setAttribute('aria-label',showPassword?'Sembunyikan kata sandi':'Tampilkan kata sandi');passwordToggle.setAttribute('aria-pressed',String(showPassword));});
    </script>
</body>
</html>
